style.css:
/* =========================================================
   ✦ ANGEL1C UNIVERSAL ✦
   Compatible con la mayoría de sitios
========================================================= */

:root{
    --angel-shadow: rgba(255,255,255,.18);
}

/* ===== Decoración ===== */

html::before,
html::after,
body::before,
body::after{
    position:fixed;
    pointer-events:none;
    z-index:2147483647;
    opacity:.18;
    font-size:34px;
    user-select:none;
}

/* Alas */

html::before{
    content:"?";
    top:12px;
    left:12px;
}

html::after{
    content:"?";
    top:12px;
    right:12px;
}

body::before{
    content:"?";
    bottom:12px;
    left:12px;
}

body::after{
    content:"?";
    bottom:12px;
    right:12px;
}

/* Scrollbar */

::-webkit-scrollbar{
    width:10px;
    height:10px;
}

::-webkit-scrollbar-thumb{
    background:#cfcfcf;
    border-radius:999px;
}

::-webkit-scrollbar-track{
    background:transparent;
}

/* Selección */

::selection{
    background:#e8e8e8;
    color:#000;
}

/* Sombras suaves en imágenes */

img{
    transition:filter .25s ease;
}

img:hover{
    filter:drop-shadow(0 0 8px var(--angel-shadow));
}

/* Botones (muy suave) */

button{
    transition:
        transform .15s ease,
        box-shadow .2s ease;
}

button:hover{
    transform:translateY(-1px);
    box-shadow:0 0 10px var(--angel-shadow);
}

/* Links */

a{
    transition:opacity .2s ease;
}

a:hover{
    opacity:.85;
}
